# Solution

def char_to_int(x):
    if x!= '0':
        return int(x)
    else:
        return 0

def reverseString(input):
    return int(''.join(reversed(input)))

def f(inputs):
    reversed_input = []
    for input in inputs:
        if len(input) > 0:
            reverse_int = 0
            for i in reversed(input):
                if i.isdigit():
                    chop_int = char_to_int(i)
                    reverse_int += chop_int
                else:
                    chop_int = reverseString(input)
                    reverse_int += chop_int
            reversed_input.append(reverse_int)
        else: reversed_input.append(float('NaN'))
    return tuple(reversed_input)

